const W = root.clientWidth || 1920, H = root.clientHeight || 1080;
const canvas = document.createElement("canvas");
canvas.width = W;
canvas.height = H;
canvas.style.cssText = "position:absolute;inset:0;width:100%;height:100%";
root.appendChild(canvas);
const renderer = new THREE.WebGLRenderer({ canvas, preserveDrawingBuffer: true });
renderer.setPixelRatio(1);
renderer.setSize(W, H, false);
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x000000);
const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 10);
camera.position.z = 1;
const corners = [[-0.6, 0.6], [0.6, 0.6], [-0.6, -0.6], [0.6, -0.6]].map(([x, y]) => {
  const tile = new THREE.Mesh(new THREE.PlaneGeometry(0.6, 0.6), new THREE.MeshBasicMaterial({ color: 0xffd27a }));
  tile.position.set(x, y, 0);
  scene.add(tile);
  return tile;
});
const draw = (t) => { corners.forEach((c) => (c.rotation.z = t * 0.1)); renderer.render(scene, camera); };
tl.to({}, { duration, ease: "none", onUpdate() { draw(this.time()); } }, 0);
draw(0);
